import { test, expect } from '@playwright/test';

test.describe('500 Error Page', () => {
  test.beforeEach(async ({ page }) => {
    // Set up route to intercept and return 500 error
    await page.route('**/*', (route) => {
      route.abort('failed');
    });
  });

  test('should display error page when server returns 500 error', async ({ page }) => {
    // Navigate to a page that will trigger the 500 error
    await page.goto('http://localhost:3000', { waitUntil: 'networkidle', timeout: 5000 }).catch(() => {
      // Expected to fail due to network abort
    });

    // Verify error message is displayed
    const errorHeading = page.getByRole('heading', { name: /error/i });
    await expect(errorHeading).toBeVisible();
  });

  test('should show error details on 500 error page', async ({ page }) => {
    // Mock a 500 response
    await page.route('**/*', (route) => {
      route.abort('failed');
    });

    await page.goto('http://localhost:3000', { waitUntil: 'networkidle', timeout: 5000 }).catch(() => {
      // Expected to fail
    });

    // Check for error status code or error message
    const errorMessage = page.getByText(/server error|500|something went wrong/i);
    await expect(errorMessage).toBeVisible();
  });

  test('should have a way to navigate back from 500 error page', async ({ page }) => {
    await page.route('**/*', (route) => {
      route.abort('failed');
    });

    await page.goto('http://localhost:3000', { waitUntil: 'networkidle', timeout: 5000 }).catch(() => {
      // Expected to fail
    });

    // Look for a back button or home link
    const backButton = page.getByRole('link', { name: /home|back|return/i }).first();
    await expect(backButton).toBeVisible();
  });
});
